function ContentCard({row,mutate}:{row:Row;mutate:Mutate}){const materialType=String(row.data.materialType||"");return <article className="rounded-[22px] border bg-white p-5"><div className="flex justify-between"><span className="grid size-11 place-items-center rounded-2xl bg-[#f8f0dc] text-[#8a5e08]">{row.kind==="course"?<BookOpen className="size-5"/>:<FileText className="size-5"/>}</span><Status status={row.status}/></div>{materialType&&<div className="mt-4 flex flex-wrap gap-2"><Badge variant="secondary">{materialType}</Badge>{row.data.subject&&<Badge variant="secondary">{String(row.data.subject)}</Badge>}</div>}<h3 className="mt-4 font-bold">{row.title}</h3>{row.data.topic&&<p className="mt-1 text-xs font-semibold text-[#8a5e08]">Tema: {String(row.data.topic)}</p>}<p className="mt-2 text-sm leading-6 text-slate-600">{String(row.data.description||"")}</p><p className="mt-4 text-xs text-slate-500">Plan {String(row.data.plan||"Bronce")}</p><div className="mt-5 flex flex-wrap gap-2">{row.data.fileKey&&<Button asChild size="sm" variant="outline"><a href={`/api/files?key=${encodeURIComponent(String(row.data.fileKey))}`}><Download/> Archivo</a></Button>}{row.data.externalUrl&&<Button asChild size="sm" variant="outline"><a href={String(row.data.externalUrl)} target="_blank" rel="noreferrer"><ChevronRight/> Abrir enlace</a></Button>}<Button size="sm" variant="outline" onClick={()=>mutate({action:"update_status",id:row.id,status:row.status==="published"?"draft":"published"},row.status==="published"?"Ocultado.":"Publicado.")}>{row.status==="published"?"Ocultar":"Publicar"}</Button></div></article>}

function Notices({rows,groups,mutate}:{rows:Row[];groups:Row[];mutate:Mutate}){const[title,setTitle]=useState(""),[body,setBody]=useState(""),[group,setGroup]=useState("all");return <div className="space-y-6"><Header eyebrow="Notificaciones" title="Avisos a estudiantes" description="Publica fechas, materiales, pagos y revisiones terminadas."/><div className="grid gap-5 xl:grid-cols-[.9fr_1.1fr]"><Panel title="Nuevo aviso"><Field label="Título"><Input value={title} onChange={e=>setTitle(e.target.value)}/></Field><Field label="Mensaje"><Textarea value={body} onChange={e=>setBody(e.target.value)}/></Field><Field label="Destinatarios"><Select value={group} onValueChange={setGroup}><SelectTrigger className="w-full"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="all">Todos</SelectItem>{groups.map(g=><SelectItem key={g.id} value={g.id}>{g.title}</SelectItem>)}</SelectContent></Select></Field><Button className="w-full bg-[#003f32]" onClick={async()=>{if(await mutate({action:"create_record",kind:"notice",title,status:"published",data:{body,groupId:group==="all"?null:group,type:"info"}},"Aviso publicado.")){setTitle("");setBody("")}}}><Send/> Publicar</Button></Panel><Panel title="Historial reciente">{rows.length?rows.slice(0,10).map(r=><div key={r.id} className="mb-3 rounded-2xl bg-slate-50 p-4"><p className="font-bold">{r.title}</p><p className="mt-2 text-sm text-slate-600">{String(r.data.body||"")}</p></div>):<p className="text-sm text-slate-500">No hay avisos.</p>}</Panel></div></div>}
function Reports({data}:{data:Workspace}){
 const [query,setQuery]=useState("");
 const r=data.records,groups=r.filter(x=>x.kind==="group"),attempts=r.filter(x=>x.kind==="attempt").sort((a,b)=>attemptTime(b)-attemptTime(a));
 const students=data.profiles.filter(profile=>profile.role==="student");
 const summaries=students.map(student=>{
  const own=attempts.filter(attempt=>attempt.created_by===student.id),scores=own.map(attempt=>Number(attempt.data.score||0));
  const latest=own[0];
  return {student,group:groups.find(group=>group.id===student.group_id),attempts:own.length,average:scores.length?scores.reduce((sum,value)=>sum+value,0)/scores.length:0,best:scores.length?Math.max(...scores):0,latest};
 }).filter(summary=>`${summary.student.full_name} ${summary.student.email} ${summary.group?.title||""}`.toLowerCase().includes(query.toLowerCase()));
 const visibleAttempts=attempts.filter(attempt=>{const student=data.profiles.find(profile=>profile.id===attempt.created_by);return `${student?.full_name||attempt.data.studentName||""} ${attempt.title} ${groups.find(group=>group.id===attempt.group_id)?.title||""}`.toLowerCase().includes(query.toLowerCase())});
 return <div className="space-y-6"><Header eyebrow="Reportes" title="Seguimiento académico" description="Consulta quién realizó cada simulador, sus notas, promedios y resultados recientes."/>
  <div className="relative max-w-md"><Search className="absolute left-3 top-1/2 size-4 -translate-y-1/2 text-slate-400"/><Input value={query} onChange={event=>setQuery(event.target.value)} className="h-11 bg-white pl-10" placeholder="Buscar estudiante, grupo o simulador"/></div>
  <Tabs defaultValue="students"><TabsList className="grid h-auto w-full grid-cols-1 gap-1 rounded-2xl border bg-white p-2 sm:grid-cols-3"><TabsTrigger className="w-full whitespace-normal" value="students">Por estudiante</TabsTrigger><TabsTrigger className="w-full whitespace-normal" value="attempts">Historial de intentos</TabsTrigger><TabsTrigger className="w-full whitespace-normal" value="general">Resumen general</TabsTrigger></TabsList>
   <TabsContent value="students" className="mt-5"><Panel title="Rendimiento por estudiante">{summaries.length?<div className="grid gap-4 lg:grid-cols-2">{summaries.map(({student,group,attempts:count,average,best,latest})=><article key={student.id} className="rounded-2xl border border-slate-200 p-4 sm:p-5"><div className="flex items-start gap-3"><span className="grid size-11 shrink-0 place-items-center rounded-full bg-[#f8f0dc] font-bold text-[#8a5e08]">{student.full_name.slice(0,2).toUpperCase()}</span><div className="min-w-0 flex-1"><h3 className="font-bold">{student.full_name}</h3><p className="mt-1 text-sm text-slate-500">{group?.title||"Sin grupo"}</p></div>{latest&&<Badge className={`shrink-0 border-0 ${latest.data.passed?"bg-emerald-100 text-emerald-800":"bg-amber-100 text-amber-800"}`}>{latest.data.passed?"Aprobado":"Necesita refuerzo"}</Badge>}</div><div className="mt-5 grid grid-cols-2 gap-3 sm:grid-cols-4"><ReportValue label="Intentos" value={String(count)}/><ReportValue label="Promedio" value={count?`${average.toFixed(2)}/20`:"—"}/><ReportValue label="Mejor nota" value={count?`${best.toFixed(2)}/20`:"—"}/><ReportValue label="Última nota" value={latest?`${Number(latest.data.score||0).toFixed(2)}/20`:"—"}/></div></article>)}</div>:<Empty icon={Users} title="Sin coincidencias" text="No encontramos estudiantes con esa búsqueda."/>}</Panel></TabsContent>
   <TabsContent value="attempts" className="mt-5"><Panel title="Intentos registrados">{visibleAttempts.length?<div className="space-y-3">{visibleAttempts.map(attempt=>{const student=data.profiles.find(profile=>profile.id===attempt.created_by),group=groups.find(item=>item.id===attempt.group_id),score=Number(attempt.data.score||0),passed=Boolean(attempt.data.passed);return <article key={attempt.id} className="rounded-2xl border border-slate-200 p-4 sm:p-5"><div className="flex flex-col gap-4 sm:flex-row sm:items-start"><div className="min-w-0 flex-1"><div className="flex flex-wrap items-center gap-2"><h3 className="font-bold">{student?.full_name||String(attempt.data.studentName||"Estudiante")}</h3><Badge className={`border-0 ${passed?"bg-emerald-100 text-emerald-800":"bg-amber-100 text-amber-800"}`}>{passed?"Aprobado":"Necesita refuerzo"}</Badge></div><p className="mt-2 font-semibold text-slate-700">{attempt.title}</p><p className="mt-1 text-sm text-slate-500">{group?.title||"Sin grupo"} · {dateTime(String(attempt.data.completedAt||attempt.created_at))}</p><p className="mt-2 text-sm text-slate-600">{Number(attempt.data.correct||0)} correctas de {Number(attempt.data.total||0)} · {duration(Number(attempt.data.durationSeconds||0))}</p></div><div className="rounded-2xl bg-[#f3f8fa] px-5 py-4 text-left sm:min-w-36 sm:text-right"><p className="text-xs font-bold uppercase tracking-wide text-slate-400">Nota</p><p className="mt-1 text-2xl font-extrabold">{score.toFixed(2)}/20</p></div></div></article>})}</div>:<Empty icon={GraduationCap} title="Sin intentos" text="Los simuladores finalizados aparecerán aquí."/>}</Panel></TabsContent>
   <TabsContent value="general" className="mt-5"><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><Metric icon={Users} label="Cuentas activas" value={data.profiles.filter(p=>p.status==="active").length} note="Incluye administrador"/><Metric icon={FileQuestion} label="Preguntas" value={r.filter(x=>x.kind==="question"&&x.status==="approved").length} note="Aprobadas" tone="gold"/><Metric icon={GraduationCap} label="Intentos" value={attempts.length} note="Simuladores finalizados" tone="coral"/><Metric icon={ClipboardCheck} label="Entregas" value={r.filter(x=>x.kind==="submission").length} note="Todas las versiones" tone="navy"/><Metric icon={CreditCard} label="Pagos aprobados" value={r.filter(x=>x.kind==="payment"&&x.status==="approved").length} note="Registros verificados"/></div></TabsContent>
  </Tabs>
 </div>
}
function Settings({email}:{email:string}){return <div className="space-y-6">
 <Header eyebrow="Configuración" title="Seguridad y funcionamiento" description="Controles independientes que protegen el acceso, los archivos y el historial sin alterar el proceso académico."/>
 <div className="grid gap-4 md:grid-cols-2">{[
  [ShieldCheck,"Acceso con doble control","Sites limita quién puede abrir la URL y ChatGPT verifica la identidad dentro de la aplicación."],
  [KeyRound,"Autorización por rol","Cada solicitud vuelve a validar cuenta activa, rol, grupo y plan; la cédula no se usa como contraseña."],
  [FolderCog,"Archivos verificados","Las cargas se validan por firma, se registran con SHA-256 y se entregan solo desde rutas privadas."],
  [History,"Auditoría protegida","Cambios de estado, pagos, planes, entregas y archivos quedan en un registro independiente no editable."],
 ].map(([Icon,title,note])=><article key={title as string} className="rounded-[24px] border bg-white p-6"><Icon className="size-6 text-[#8a5e08]"/><h2 className="mt-4 font-bold">{title as string}</h2><p className="mt-2 text-sm leading-6 text-slate-600">{note as string}</p></article>)}</div>
 <section className="rounded-[24px] bg-[#003f32] p-6 text-white"><div className="flex flex-col gap-5 sm:flex-row sm:items-center sm:justify-between"><div><h2 className="font-bold">Respaldo lógico administrado</h2><p className="mt-2 max-w-2xl text-sm leading-6 text-slate-300">Descarga una copia de D1 con el inventario de archivos R2. El acceso está limitado, auditado y protegido contra descargas repetitivas.</p></div><Button asChild className="shrink-0 bg-white text-[#003f32] hover:bg-slate-100"><a href="/api/security/backup"><Download/> Descargar respaldo</a></Button></div></section>
 <section className="rounded-[24px] border border-amber-200 bg-amber-50 p-6"><h2 className="font-bold text-amber-950">Copia externa de archivos pendiente</h2><p className="mt-2 text-sm leading-6 text-amber-900">El respaldo descargable conserva los datos y el inventario, pero una recuperación total también requiere copiar fuera del Site los binarios privados de R2. Se configurará cuando se elija el destino externo.</p></section>
 <p className="rounded-2xl border bg-white p-4 text-sm">Cuenta administradora: <strong>{email}</strong></p>
 </div>}

type SimulatorQuestion = { questionId:string; subject:string; topic:string; format:string; prompt:string; caseContext?:string|null; sourceMaterialTitle?:string|null; sourceMaterialType?:string|null; options:string[] };
type SimulatorReview = SimulatorQuestion & { selectedIndex:number; correctIndex:number; correct:boolean; explanation:string; source:string };
type SimulatorResult = { correct:number; total:number; score:number; passScore:number; passed:boolean; completedAt:string; review:SimulatorReview[] };
type SimulatorAttempt = { id:string; startedAt:string; questions:SimulatorQuestion[] };
type PreparedQuestion = { row:Row; options:Array<{label:string;originalIndex:number}> };
type PracticeFeedback = { correct:boolean; correctIndex:number; explanation:string; source:string };
type SimulatorDistribution = { subject:string; count:number };

function shuffle<T>(values:T[]){const next=[...values];for(let i=next.length-1;i>0;i--){const j=Math.floor(Math.random()*(i+1));[next[i],next[j]]=[next[j],next[i]];}return next;}
function simulatorDistribution(row?:Row|null):SimulatorDistribution[]{if(!row||!Array.isArray(row.data.distribution))return [];return row.data.distribution.flatMap((item:unknown)=>{if(!item||typeof item!=="object")return [];const value=item as Record<string,unknown>,subject=String(value.subject||""),count=Number(value.count);return subject&&Number.isInteger(count)&&count>0?[{subject,count}]:[];});}
function isFinalSimulator(row:Row){return row.data.mode==="final"||["General","23 materias"].includes(String(row.data.subject||"General"));}
function simulatorPlannedCount(row:Row){const distribution=simulatorDistribution(row);return distribution.length?distribution.reduce((sum,item)=>sum+item.count,0):Math.max(1,Number(row.data.count)||20);}
function prepareSimulator(rows:Row[],simulator:Row):PreparedQuestion[]{const areaRows=rows.filter(row=>row.data.area===simulator.data.area&&row.data.period===simulator.data.period),distribution=simulatorDistribution(simulator);let selectedRows:Row[];if(isFinalSimulator(simulator)&&distribution.length){selectedRows=distribution.flatMap(item=>shuffle(areaRows.filter(row=>row.data.subject===item.subject)).slice(0,item.count));}else{const subject=String(simulator.data.subject||"General"),compatible=["General","23 materias"].includes(subject)?areaRows:areaRows.filter(row=>row.data.subject===subject);selectedRows=shuffle(compatible).slice(0,simulatorPlannedCount(simulator));}return shuffle(selectedRows).map(row=>({row,options:shuffle(((row.data.options||[]) as string[]).map((label,originalIndex)=>({label,originalIndex})))}));}
function newClientAttemptId(){return typeof crypto!=="undefined"&&"randomUUID" in crypto?crypto.randomUUID():`${Date.now()}_${Math.random().toString(36).slice(2)}`;}

function StudentAcademic({title,description,area,subjects,plan,resources,questions,sims,attempts,preview}:{title:string;description:string;area:keyof SubjectCatalog;subjects:string[];plan:string;resources:Row[];questions:Row[];sims:Row[];attempts:Row[];preview:boolean}){
 const[active,setActive]=useState<Row|null>(null),[selectedSubject,setSelectedSubject]=useState(subjects[0]||""),[materialType,setMaterialType]=useState("Todos"),[academicView,setAcademicView]=useState("subjects"),[subjectTab,setSubjectTab]=useState("content");
 const complex=area==="complexive",qq=questions.filter(r=>r.data.area===area),ss=sims.filter(r=>r.data.area===area),rr=resources.filter(r=>r.data.area===area);
 const currentSubject=subjects.includes(selectedSubject)?selectedSubject:subjects[0]||"",subjectResources=rr.filter(r=>r.data.subject===currentSubject),contentRows=materialType==="Todos"?subjectResources:subjectResources.filter(r=>r.data.materialType===materialType);
 const practiceRows=qq.filter(r=>r.data.subject===currentSubject);
 const subjectSimulatorCards=ss.filter(r=>!isFinalSimulator(r)&&r.data.subject===currentSubject),finalSimulatorCards=ss.filter(isFinalSimulator);
 const simulatorRows=active?qq:[];
 const simulatorCount=active?simulatorPlannedCount(active):0,subjectNumber=Math.max(1,subjects.indexOf(currentSubject)+1),areaLabel=complex?"Complexivos":"Fin de Carrera";
 return <div className="space-y-6">
  <Header eyebrow={`${title} · Plan ${plan}`} title={complex?"Ruta de estudio y simuladores":"Materias, práctica y simuladores"} description={description}/>
  <Tabs value={academicView} onValueChange={setAcademicView}>
   <TabsList className="grid h-auto w-full grid-cols-1 gap-3 bg-transparent p-0 sm:grid-cols-2">
    <TabsTrigger value="subjects" className="h-auto min-h-20 justify-start gap-3 rounded-[22px] border bg-white p-4 text-left shadow-none data-[state=active]:border-[#d6a32b] data-[state=active]:bg-[#fff9eb] data-[state=active]:ring-2 data-[state=active]:ring-[#d6a32b]/15"><span className="grid size-11 shrink-0 place-items-center rounded-2xl bg-[#f8f0dc] text-[#8a5e08]"><BookOpenCheck className="size-5"/></span><span><strong className="block text-base">Estudio por materia</strong><small className="mt-1 block font-normal text-slate-500">Materiales, práctica y simulador individual</small></span></TabsTrigger>
    <TabsTrigger value="final" className="group h-auto min-h-20 justify-start gap-3 rounded-[22px] border bg-white p-4 text-left shadow-none data-[state=active]:border-[#003f32] data-[state=active]:bg-[#003f32] data-[state=active]:text-white data-[state=active]:ring-2 data-[state=active]:ring-[#003f32]/15"><span className="grid size-11 shrink-0 place-items-center rounded-2xl bg-[#eaf0f5] text-[#0a4b3e] group-data-[state=active]:bg-white/10 group-data-[state=active]:text-[#f4d37b]"><GraduationCap className="size-5"/></span><span><strong className="block text-base">Examen final</strong><small className="mt-1 block font-normal text-slate-500 group-data-[state=active]:text-white/70">Evaluación combinada de las materias</small></span></TabsTrigger>
   </TabsList>

   <TabsContent value="subjects" className="mt-6 space-y-6">
    <StudentSubjectNav subjects={subjects} value={currentSubject} onChange={subject=>{setSelectedSubject(subject);setMaterialType("Todos");setSubjectTab("content")}} resources={rr} questions={qq} simulators={ss}/>
    {currentSubject&&<section className="overflow-hidden rounded-[28px] border bg-white"><div className="border-b bg-[#f8faf9] p-5 sm:p-6"><div className="flex flex-col gap-4 sm:flex-row sm:items-center sm:justify-between"><div><Badge variant="secondary">Materia {subjectNumber} de {subjects.length}</Badge><h2 className="mt-3 text-2xl font-extrabold">{currentSubject}</h2><p className="mt-2 text-sm leading-6 text-slate-500">Avanza por los tres espacios de esta materia antes de pasar al examen final.</p></div><div className="flex items-center gap-2 rounded-2xl border bg-white px-4 py-3 text-sm"><BookOpen className="size-5 text-[#8a5e08]"/><span><strong className="block">Ruta de materia</strong><small className="text-slate-500">Contenido → Práctica → Simulador</small></span></div></div></div>
     <div className="p-4 sm:p-6"><Tabs value={subjectTab} onValueChange={setSubjectTab}><TabsList className="mb-6 h-auto w-full justify-start overflow-x-auto overflow-y-hidden rounded-2xl border bg-slate-50 p-1.5 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"><TabsTrigger className="min-h-11 flex-none px-4 text-sm sm:flex-1" value="content"><span className="mr-2 grid size-6 place-items-center rounded-full bg-[#003f32] text-xs font-bold text-white">1</span>Materiales</TabsTrigger><TabsTrigger className="min-h-11 flex-none px-4 text-sm sm:flex-1" value="bank"><span className="mr-2 grid size-6 place-items-center rounded-full bg-[#003f32] text-xs font-bold text-white">2</span>Práctica</TabsTrigger><TabsTrigger className="min-h-11 flex-none px-4 text-sm sm:flex-1" value="simulator"><span className="mr-2 grid size-6 place-items-center rounded-full bg-[#003f32] text-xs font-bold text-white">3</span>Simulador</TabsTrigger></TabsList>
      <TabsContent value="content" className="space-y-5"><MaterialTypeFilter value={materialType} onChange={setMaterialType} rows={subjectResources}/><TopicGroups rows={contentRows} render={row=><StudentCard key={row.id} row={row}/>}/></TabsContent>
      <TabsContent value="bank">{practiceRows.length?<Practice key={`${area}-${currentSubject}`} rows={practiceRows} preview={preview}/>:<Empty icon={FileQuestion} title="Banco en preparación" text="Todavía no hay preguntas publicadas para esta materia."/>}</TabsContent>
      <TabsContent value="simulator"><div className="space-y-4"><div><p className="text-sm font-bold text-[#8a5e08]">Paso 3 de la materia</p><h3 className="mt-1 text-xl font-bold">Simulador de {currentSubject}</h3><p className="mt-2 text-sm text-slate-500">Este simulador utiliza únicamente preguntas aprobadas de esta materia.</p></div>{subjectSimulatorCards.length?<div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{subjectSimulatorCards.map(r=><StudentCard key={r.id} row={r} onOpen={()=>setActive(r)}/>)}</div>:<Empty icon={FileQuestion} title="Simulador en preparación" text="Aparecerá cuando el profesor configure y publique el simulador de esta materia."/>}</div></TabsContent>
     </Tabs></div></section>}
   </TabsContent>

   <TabsContent value="final" className="mt-6 space-y-5"><section className="rounded-[28px] bg-[#003f32] p-6 text-white sm:p-8"><div className="flex flex-col gap-5 sm:flex-row sm:items-center sm:justify-between"><div className="max-w-2xl"><p className="text-sm font-bold text-[#f4d37b]">Paso final</p><h2 className="mt-2 text-2xl font-extrabold sm:text-3xl">Examen final de {areaLabel}</h2><p className="mt-3 text-sm leading-6 text-white/70">Combina preguntas de las materias definidas por el profesor. Es independiente de los simuladores individuales.</p></div><span className="grid size-16 shrink-0 place-items-center rounded-[22px] bg-white/10 text-[#f4d37b]"><GraduationCap className="size-8"/></span></div><div className="mt-6 flex flex-wrap gap-2"><Badge className="border-0 bg-white/10 text-white">{subjects.length} materia(s)</Badge><Badge className="border-0 bg-white/10 text-white">Plan {plan}</Badge><Badge className="border-0 bg-white/10 text-white">{finalSimulatorCards.length?"Disponible":"En preparación"}</Badge></div></section>{finalSimulatorCards.length?<div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{finalSimulatorCards.map(r=><StudentCard key={r.id} row={r} onOpen={()=>setActive(r)}/>)}</div>:<Empty icon={GraduationCap} title="Examen final en preparación" text="Aparecerá cuando el profesor defina las materias, cantidades y lo publique."/>}{complex&&<Panel title="Referencia histórica 2025-2026"><p className="text-sm leading-6 text-slate-600">La estructura anterior utilizó 20 preguntas: 5 de completar, 5 directas contextualizadas, 5 de relacionar y 5 de ordenar. Es una referencia editable, no una regla para periodos nuevos.</p></Panel>}</TabsContent>
  </Tabs>
  <Dialog open={Boolean(active)} onOpenChange={open=>{if(!open)setActive(null)}}><DialogContent className="max-h-[92vh] overflow-y-auto sm:max-w-5xl"><DialogHeader><DialogTitle>{active?.title}</DialogTitle><DialogDescription>{simulatorCount} preguntas aleatorias. Las respuestas y explicaciones se muestran únicamente al finalizar.</DialogDescription></DialogHeader>{active&&simulatorRows.length?<SimulatorSession key={active.id} simulator={active} rows={simulatorRows} attempts={attempts} preview={preview}/>:<Empty icon={FileQuestion} title="Sin preguntas compatibles" text="El profesor debe aprobar preguntas de esta materia antes de publicar el simulador."/>}</DialogContent></Dialog>
 </div>;
}

function SimulatorSession({simulator,rows,attempts,preview}:{simulator:Row;rows:Row[];attempts:Row[];preview:boolean}){
 const[requestId,setRequestId]=useState(newClientAttemptId),[attempt,setAttempt]=useState<SimulatorAttempt|null>(null),[previewKey,setPreviewKey]=useState<Record<string,number>>({}),[index,setIndex]=useState(0),[answers,setAnswers]=useState<Record<string,number>>({}),[result,setResult]=useState<SimulatorResult|null>(null),[loading,setLoading]=useState(true),[saving,setSaving]=useState(false),[startError,setStartError]=useState("");
 useEffect(()=>{let cancelled=false;const begin=async()=>{setLoading(true);setStartError("");setAttempt(null);setResult(null);setIndex(0);setAnswers({});try{if(preview){const prepared=prepareSimulator(rows,simulator),key:Record<string,number>={};const questions=prepared.map(question=>{const correctOriginal=Number(question.row.data.correctIndex),correctIndex=question.options.findIndex(option=>option.originalIndex===correctOriginal);key[question.row.id]=correctIndex;return {questionId:question.row.id,subject:String(question.row.data.subject||""),topic:String(question.row.data.topic||""),format:String(question.row.data.format||""),prompt:String(question.row.data.prompt||""),caseContext:String(question.row.data.caseContext||"")||null,sourceMaterialTitle:String(question.row.data.sourceMaterialTitle||"")||null,sourceMaterialType:String(question.row.data.sourceMaterialType||"")||null,options:question.options.map(option=>option.label)}});if(!cancelled){setPreviewKey(key);setAttempt({id:`preview-${requestId}`,startedAt:new Date().toISOString(),questions});}return;}const response=await fetch("/api/platform",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"start_simulator_attempt",simulatorId:simulator.id,clientAttemptId:requestId})});const payload=await response.json() as {error?:string;attempt?:SimulatorAttempt};if(!response.ok||!payload.attempt)throw new Error(payload.error||"No se pudo iniciar el simulador.");if(!cancelled)setAttempt(payload.attempt);}catch(error){if(!cancelled)setStartError(error instanceof Error?error.message:"No se pudo iniciar el simulador.");}finally{if(!cancelled)setLoading(false);}};void begin();return()=>{cancelled=true};},[preview,requestId,rows,simulator]);
 const prepared=attempt?.questions||[],current=prepared[index],selected=current?answers[current.questionId]:undefined,answered=Object.keys(answers).length,allAnswered=prepared.length>0&&answered===prepared.length;
 const finish=async()=>{if(!attempt||!allAnswered)return toast.error("Responde todas las preguntas antes de finalizar.");setSaving(true);try{if(preview){const review:SimulatorReview[]=attempt.questions.map(question=>{const source=rows.find(row=>row.id===question.questionId),selectedIndex=answers[question.questionId],correctIndex=previewKey[question.questionId];return {...question,selectedIndex,correctIndex,correct:selectedIndex===correctIndex,explanation:String(source?.data.explanation||""),source:String(source?.data.source||"")}});const correct=review.filter(question=>question.correct).length,total=review.length,score=Math.round((correct/total)*2000)/100,passScore=Number(simulator.data.passScore||14);setResult({correct,total,score,passScore,passed:score>=passScore,completedAt:new Date().toISOString(),review});return;}const response=await fetch("/api/platform",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"finish_simulator_attempt",attemptId:attempt.id,answers:attempt.questions.map(question=>({questionId:question.questionId,selectedIndex:answers[question.questionId]}))})});const payload=await response.json() as {error?:string;result?:SimulatorResult};if(!response.ok||!payload.result)throw new Error(payload.error||"No se pudo finalizar el simulador.");setResult(payload.result);toast.success("Resultado guardado en tu historial.");}catch(error){toast.error(error instanceof Error?error.message:"No se pudo finalizar el simulador.");}finally{setSaving(false);}};
 const restart=()=>setRequestId(newClientAttemptId());
 if(loading)return <div className="grid min-h-72 place-items-center rounded-[24px] border bg-white"><div className="text-center"><RefreshCw className="mx-auto size-7 animate-spin text-[#8a5e08]"/><p className="mt-4 text-sm font-semibold text-slate-600">Preparando un intento protegido…</p></div></div>;
 if(startError||!attempt)return <div className="rounded-[24px] border border-amber-200 bg-amber-50 p-6 text-center"><AlertTriangle className="mx-auto size-8 text-amber-600"/><h3 className="mt-4 font-bold">No se pudo iniciar el simulador</h3><p className="mt-2 text-sm text-slate-600">{startError||"Intenta nuevamente."}</p><Button onClick={restart} variant="outline" className="mt-5 bg-white"><RefreshCw/> Reintentar</Button></div>;
 if(result){const stored=attempts.filter(item=>item.data.simulatorId===simulator.id).sort((a,b)=>new Date(a.created_at).getTime()-new Date(b.created_at).getTime()),hasCurrent=stored.some(item=>item.data.completedAt===result.completedAt),scores=stored.map(item=>Number(item.data.score||0));if(!hasCurrent)scores.push(result.score);const average=scores.reduce((sum,value)=>sum+value,0)/Math.max(scores.length,1);return <div className="space-y-5"><section className={`rounded-[24px] border p-6 ${result.passed?"border-emerald-300 bg-emerald-50":"border-amber-300 bg-amber-50"}`}><div className="flex flex-col gap-5 sm:flex-row sm:items-center sm:justify-between"><div><Badge className={result.passed?"border-0 bg-emerald-600 text-white":"border-0 bg-amber-500 text-[#352400]"}>{result.passed?"Aprobado":"Necesita refuerzo"}</Badge><h3 className="mt-4 text-3xl font-extrabold">{result.score.toFixed(2)}/20</h3><p className="mt-2 text-sm text-slate-600">{result.correct} respuestas correctas de {result.total}. Nota mínima: {result.passScore}/20.</p></div><Button onClick={restart} variant="outline" className="bg-white"><RefreshCw/> Nuevo intento</Button></div></section><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><Metric icon={History} label="Primer resultado" value={`${(scores[0]??result.score).toFixed(2)}/20`} note="Primer intento"/><Metric icon={CheckCircle2} label="Último resultado" value={`${(scores.at(-1)??result.score).toFixed(2)}/20`} note="Intento más reciente"/><Metric icon={GraduationCap} label="Mejor resultado" value={`${Math.max(...scores).toFixed(2)}/20`} note={`${scores.length} intento(s)`}/><Metric icon={BarChart3} label="Promedio" value={`${average.toFixed(2)}/20`} note="Historial personal"/></div><Panel title="Revisión del intento"><div className="space-y-3">{result.review.map((question,questionIndex)=><article key={question.questionId} className={`rounded-2xl border p-4 ${question.correct?"border-emerald-200 bg-emerald-50/60":"border-rose-200 bg-rose-50/60"}`}>{question.sourceMaterialTitle&&<p className="mb-3 rounded-xl bg-white/70 p-3 text-sm"><strong>Material de origen:</strong> {question.sourceMaterialType||"Material"} · {question.sourceMaterialTitle}</p>}{question.caseContext&&<div className="mb-3 rounded-xl border border-amber-200 bg-white/70 p-3 text-sm leading-6"><strong className="text-[#8a5e08]">Caso:</strong> {question.caseContext}</div>}<div className="flex items-start justify-between gap-3"><p className="font-semibold leading-6">{questionIndex+1}. {question.prompt}</p><Badge variant="secondary">{question.correct?"Correcta":"Incorrecta"}</Badge></div><p className="mt-3 text-sm"><strong>Tu respuesta:</strong> {String.fromCharCode(65+question.selectedIndex)}. {question.options[question.selectedIndex]}</p>{!question.correct&&<p className="mt-2 text-sm text-emerald-800"><strong>Respuesta correcta:</strong> {String.fromCharCode(65+question.correctIndex)}. {question.options[question.correctIndex]}</p>}<p className="mt-3 text-sm leading-6 text-slate-600">{question.explanation}</p><p className="mt-2 text-xs text-slate-500">Fuente: {question.source||"Sin fuente registrada"}</p></article>)}</div></Panel></div>}
 return <div className="grid gap-5 xl:grid-cols-[1fr_260px]"><section className="rounded-[24px] border bg-white p-5 sm:p-6"><div className="flex items-center justify-between gap-3"><Badge variant="secondary">{current.topic||"Pregunta"}</Badge><span className="text-sm font-bold">{index+1}/{prepared.length}</span></div>{current.sourceMaterialTitle&&<p className="mt-4 rounded-xl bg-sky-50 p-3 text-sm text-slate-700"><strong>Material de origen:</strong> {current.sourceMaterialType||"Material"} · {current.sourceMaterialTitle}</p>}{current.caseContext&&<div className="mt-5 rounded-2xl border border-amber-200 bg-[#fff9eb] p-4"><p className="text-xs font-extrabold uppercase tracking-[0.16em] text-[#8a5e08]">Contexto del caso</p><p className="mt-2 text-sm leading-6 text-slate-700">{current.caseContext}</p></div>}<h3 className="mt-5 text-lg font-bold leading-8">{current.prompt}</h3><div className="mt-5 space-y-3">{current.options.map((option,optionIndex)=><button key={`${current.questionId}-${optionIndex}`} onClick={()=>setAnswers(value=>({...value,[current.questionId]:optionIndex}))} className={`w-full rounded-2xl border p-4 text-left text-sm leading-6 transition ${selected===optionIndex?"border-[#d6a32b] bg-[#fff9eb] ring-2 ring-[#d6a32b]/15":"bg-white hover:border-slate-400"}`}><strong>{String.fromCharCode(65+optionIndex)}.</strong> {option}</button>)}</div><div className="mt-6 flex flex-wrap justify-between gap-3"><Button variant="outline" disabled={index===0} onClick={()=>setIndex(value=>value-1)}>Anterior</Button>{index<prepared.length-1?<Button disabled={selected===undefined} onClick={()=>setIndex(value=>value+1)} className="bg-[#003f32]">Siguiente <ChevronRight/></Button>:<Button disabled={!allAnswered||saving} onClick={finish} className="bg-[#003f32]">{saving?<RefreshCw className="animate-spin"/>:<CheckCircle2/>} Finalizar</Button>}</div></section><aside className="rounded-[24px] bg-[#003f32] p-5 text-white"><p className="text-sm font-bold text-[#f3d277]">Simulador</p><p className="mt-4 text-4xl font-extrabold">{answered}/{prepared.length}</p><p className="text-sm text-slate-300">respondidas</p><Progress value={(answered/prepared.length)*100} className="mt-5 bg-white/15 [&_[data-slot=progress-indicator]]:bg-[#edc764]"/><div className="mt-6 grid grid-cols-5 gap-2">{prepared.map((question,questionIndex)=><button key={question.questionId} onClick={()=>setIndex(questionIndex)} aria-label={`Ir a la pregunta ${questionIndex+1}`} className={`grid size-9 place-items-center rounded-lg text-xs font-bold ${questionIndex===index?"bg-white text-[#003f32]":answers[question.questionId]!==undefined?"bg-[#d6a32b] text-[#392600]":"bg-white/10 text-white"}`}>{questionIndex+1}</button>)}</div><p className="mt-6 text-xs leading-5 text-slate-300">El servidor seleccionó este intento. La clave se mantiene protegida hasta finalizar.</p></aside></div>;
}
function StudentCard({row,onOpen}:{row:Row;onOpen?:()=>void}){const materialType=String(row.data.materialType||""),description=row.kind==="simulator"?`${simulatorPlannedCount(row)} preguntas · Plan ${row.data.plan||"Plata"}`:String(row.data.description||"");return <article className="rounded-[22px] border bg-white p-5"><div className="flex justify-between"><span className="grid size-11 place-items-center rounded-2xl bg-[#f8f0dc] text-[#8a5e08]">{row.kind==="simulator"?<GraduationCap className="size-5"/>:<FileText className="size-5"/>}</span><Badge variant="secondary">{String(row.data.period||row.data.plan||"")}</Badge></div>{materialType&&<div className="mt-4 flex flex-wrap gap-2"><Badge variant="secondary">{materialType}</Badge>{row.data.subject&&<Badge variant="secondary">{String(row.data.subject)}</Badge>}</div>}<h3 className="mt-4 font-bold">{row.title}</h3>{row.data.topic&&<p className="mt-1 text-xs font-semibold text-[#8a5e08]">Tema: {String(row.data.topic)}</p>}<p className="mt-2 text-sm leading-6 text-slate-600">{description}</p>{row.data.fileKey?<Button asChild variant="outline" className="mt-5 w-full"><a href={`/api/files?key=${encodeURIComponent(String(row.data.fileKey))}`}><Download/> {materialType==="Audio"?"Descargar audio":"Descargar"}</a></Button>:row.data.externalUrl?<Button asChild className="mt-5 w-full bg-[#003f32]"><a href={String(row.data.externalUrl)} target="_blank" rel="noreferrer"><ChevronRight/> Abrir {materialType==="Video"?"video":"enlace"}</a></Button>:onOpen?<Button onClick={onOpen} className="mt-5 w-full bg-[#003f32]">Comenzar</Button>:<p className="mt-5 rounded-xl bg-slate-50 px-3 py-2 text-center text-xs font-semibold text-slate-500">Contenido publicado</p>}</article>}
function Practice({rows,preview}:{rows:Row[];preview:boolean}){
 const[index,setIndex]=useState(0),[selected,setSelected]=useState<number|null>(null),[feedback,setFeedback]=useState<Record<string,PracticeFeedback>>({}),[finished,setFinished]=useState(false),[checking,setChecking]=useState(false);
 const row=rows[index],options=(row.data.options||[]) as string[],correct=Object.values(feedback).filter(item=>item.correct).length,currentFeedback=feedback[row.id];
 const restart=()=>{setIndex(0);setSelected(null);setFeedback({});setFinished(false)};
 if(finished)return <section className="rounded-[24px] border border-emerald-200 bg-emerald-50/60 p-6"><Badge className="border-0 bg-emerald-600 text-white">Práctica completada</Badge><h3 className="mt-4 text-2xl font-extrabold">{correct} de {rows.length} respuesta{rows.length===1?"":"s"} correcta{rows.length===1?"":"s"}</h3><p className="mt-2 text-sm leading-6 text-slate-600">Revisaste todas las preguntas disponibles de esta materia.</p><Button onClick={restart} variant="outline" className="mt-5 bg-white"><RefreshCw/> Practicar de nuevo</Button></section>;
 const isLast=index===rows.length-1;
 const choose=async(optionIndex:number)=>{setSelected(optionIndex);setChecking(true);try{if(preview){const correctIndex=Number(row.data.correctIndex);setFeedback(value=>({...value,[row.id]:{correct:optionIndex===correctIndex,correctIndex,explanation:String(row.data.explanation||""),source:String(row.data.source||"")}}));return;}const response=await fetch("/api/platform",{method:"POST",headers:{"content-type":"application/json"},body:JSON.stringify({action:"check_practice_answer",questionId:row.id,selectedIndex:optionIndex})});const payload=await response.json() as {error?:string;feedback?:PracticeFeedback};if(!response.ok||!payload.feedback)throw new Error(payload.error||"No se pudo comprobar la respuesta.");setFeedback(value=>({...value,[row.id]:payload.feedback!}));}catch(error){setSelected(null);toast.error(error instanceof Error?error.message:"No se pudo comprobar la respuesta.");}finally{setChecking(false)}};
 const advance=()=>{if(isLast){setFinished(true);return}setIndex(value=>value+1);setSelected(null)};
 return <div className="grid gap-5 xl:grid-cols-[1fr_280px]"><section className="rounded-[24px] border bg-white p-6"><div className="flex justify-between"><Badge variant="secondary">{String(row.data.topic||"")}</Badge><span className="text-sm font-bold">{index+1}/{rows.length}</span></div>{row.data.sourceMaterialTitle&&<p className="mt-4 rounded-xl bg-sky-50 p-3 text-sm text-slate-700"><strong>Material de origen:</strong> {String(row.data.sourceMaterialType||"Material")} · {String(row.data.sourceMaterialTitle)}</p>}{row.data.caseContext&&<div className="mt-5 rounded-2xl border border-amber-200 bg-[#fff9eb] p-4"><p className="text-xs font-extrabold uppercase tracking-[0.16em] text-[#8a5e08]">Contexto del caso</p><p className="mt-2 text-sm leading-6 text-slate-700">{String(row.data.caseContext)}</p></div>}<h3 className="mt-5 font-bold leading-7">{String(row.data.prompt||"")}</h3><div className="mt-5 space-y-3">{options.map((o,i)=><button key={o} disabled={selected!==null||checking} onClick={()=>void choose(i)} className={`w-full rounded-2xl border p-4 text-left text-sm ${currentFeedback&&i===currentFeedback.correctIndex?"border-emerald-400 bg-emerald-50":currentFeedback&&selected===i?"border-rose-300 bg-rose-50":selected===i?"border-[#d6a32b] bg-[#fff9eb]":""}`}><strong>{String.fromCharCode(65+i)}.</strong> {o}</button>)}</div>{checking&&<p className="mt-5 flex items-center gap-2 rounded-2xl bg-slate-50 p-4 text-sm text-slate-600"><RefreshCw className="size-4 animate-spin"/> Comprobando la respuesta…</p>}{currentFeedback&&<p className="mt-5 rounded-2xl bg-slate-50 p-4 text-sm leading-6">{currentFeedback.explanation}<small className="mt-2 block text-slate-500">Fuente: {currentFeedback.source}</small></p>}<Button disabled={!currentFeedback||checking} onClick={advance} className="mt-5 bg-[#003f32]">{isLast?<><CheckCircle2/> Finalizar práctica</>:<>Siguiente <ChevronRight/></>}</Button></section><aside className="rounded-[24px] bg-[#003f32] p-5 text-white"><p className="text-sm font-bold text-[#f3d277]">Práctica libre</p><p className="mt-4 text-4xl font-extrabold">{index+1}</p><p className="text-sm text-slate-300">pregunta actual</p><Progress value={((index+1)/rows.length)*100} className="mt-5 bg-white/15 [&_[data-slot=progress-indicator]]:bg-[#edc764]"/></aside></div>
}

function StudentWork({profile,preview,canSubmit,mutate,upload}:{profile:Profile;preview:boolean;canSubmit:boolean;mutate:Mutate;upload:(f:File,k:string,g?:string)=>Promise<any>}){const[type,setType]=useState("planning"),[title,setTitle]=useState(""),[notes,setNotes]=useState(""),[file,setFile]=useState<File|null>(null),[busy,setBusy]=useState(false);return <div className="space-y-6"><Header eyebrow="Trabajos UIC" title="Planificación y estudio de caso" description="Cuando un integrante entrega, todo el grupo ve el mismo estado e historial."/><div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><div className="space-y-3">{[["planning","Planificación curricular",ClipboardCheck],["case-study","Estudio de caso",FileCheck2]].map(([id,label,Icon])=><button key={id as string} onClick={()=>setType(id as string)} className={`flex w-full items-center gap-4 rounded-[22px] border p-5 text-left ${type===id?"border-[#d6a32b] bg-[#fff9eb]":"bg-white"}`}><span className="grid size-11 place-items-center rounded-2xl bg-[#003f32] text-white"><Icon className="size-5"/></span><strong>{label as string}</strong></button>)}</div><Panel title="Nueva entrega"><Field label="Nombre del trabajo"><Input value={title} onChange={e=>setTitle(e.target.value)}/></Field><Field label="Indicaciones"><Textarea value={notes} onChange={e=>setNotes(e.target.value)}/></Field><FilePicker file={file} setFile={setFile} label="Seleccionar archivo"/><Button disabled={busy||preview||!profile.group_id||!canSubmit} className="w-full bg-[#003f32]" onClick={async()=>{if(!file||!title)return toast.error("Completa el nombre y el archivo.");setBusy(true);const stored=await upload(file,"submission");if(stored)await mutate({action:"submit_work",title,workType:type,notes,fileKey:stored.key,fileName:stored.fileName},"Entrega registrada para el grupo.");setBusy(false)}}>{busy?<RefreshCw className="animate-spin"/>:<Send/>} {preview?"Vista previa":!profile.group_id?"Primero debes pertenecer a un grupo":canSubmit?"Enviar al profesor":"Requiere plan Plata o Gold"}</Button></Panel></div><p className="rounded-2xl bg-[#fff7e5] p-4 text-sm leading-6 text-[#76520a]">Plata incluye una revisión por proyecto; Gold incluye hasta tres. Una corrección del mismo documento permanece en la misma solicitud.</p></div>}
function StudentResources({plan,resources,courses}:{plan:string;resources:Row[];courses:Row[]}){return <div className="space-y-6"><Header eyebrow="Recursos adicionales" title="Currículo, cursos y apoyo académico" description="Documentos, videos, rúbricas, modelos y rutas publicados por el profesor."/><Tabs defaultValue="curriculum"><TabsList className="mb-5 h-auto w-full justify-start overflow-x-auto overflow-y-hidden rounded-2xl border bg-white p-1.5 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"><TabsTrigger className="min-h-10 flex-none px-4 text-sm sm:flex-1" value="curriculum">Currículo</TabsTrigger><TabsTrigger className="min-h-10 flex-none px-4 text-sm sm:flex-1" value="courses">Cursos</TabsTrigger><TabsTrigger className="min-h-10 flex-none px-4 text-sm sm:flex-1" value="apa">Normas APA</TabsTrigger><TabsTrigger className="min-h-10 flex-none px-4 text-sm sm:flex-1" value="other">Otros materiales</TabsTrigger></TabsList><TabsContent value="curriculum"><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{resources.filter(r=>r.data.category==="curriculum").map(r=><StudentCard key={r.id} row={r}/>)}</div></TabsContent><TabsContent value="courses"><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{courses.map(r=><StudentCard key={r.id} row={r}/>)}</div></TabsContent><TabsContent value="apa"><Apa plan={plan}/></TabsContent><TabsContent value="other"><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{resources.filter(r=>!['curriculum','apa'].includes(String(r.data.category))).map(r=><StudentCard key={r.id} row={r}/>)}</div></TabsContent></Tabs></div>}
function Deliveries({rows}:{rows:Row[]}){return <div className="space-y-6"><Header eyebrow="Entregas y revisiones" title="Historial del grupo" description="Consulta archivos, plazos, observaciones y versiones."/>{rows.length?rows.map(r=><article key={r.id} className="rounded-[22px] border bg-white p-5"><div className="flex flex-col gap-4 md:flex-row"><div className="flex-1"><div className="flex flex-wrap gap-2"><Status status={r.status}/><Badge variant="secondary">{workTypeLabel(r.data.workType)}</Badge></div><h3 className="mt-3 font-bold">{r.title}</h3><p className="mt-1 text-sm text-slate-500">{String(r.data.submittedByName||"")} · {date(r.updated_at)} · {Number(r.data.revisions||0)+1} versión(es)</p><p className="mt-3 flex items-center gap-2 text-sm font-semibold text-[#0b5143]"><CalendarDays className="size-4"/> {r.data.dueAt?`Plazo: ${dateOnly(r.data.dueAt)}`:"Sin plazo definido"}</p>{r.data.reviewNotes&&<p className="mt-4 rounded-xl bg-slate-50 p-4 text-sm">{String(r.data.reviewNotes)}</p>}</div><div className="flex flex-wrap gap-2">{r.data.fileKey&&<Button asChild variant="outline"><a href={`/api/files?key=${encodeURIComponent(String(r.data.fileKey))}`}><Download/> Original</a></Button>}{r.data.reviewFileKey&&<Button asChild className="bg-[#003f32]"><a href={`/api/files?key=${encodeURIComponent(String(r.data.reviewFileKey))}`}><Download/> Corrección</a></Button>}</div></div></article>):<Empty icon={FileCheck2} title="Todavía no hay entregas" text="Las solicitudes del grupo aparecerán aquí."/>}</div>}
function Group({data,group,preview}:{data:Workspace;group?:Row;preview:boolean}){const people=preview?[{id:"1",full_name:"Coordinador del grupo",email:"correo@ejemplo.com",role:"student",status:"active",member_role:"coordinator"} as Profile]:data.profiles;return <div className="space-y-6"><Header eyebrow="Mi grupo" title={preview?"Vista de estudiante":group?.title||"Sin grupo asignado"} description="El grupo comparte plan, entregas, revisiones e historial."/><div className="grid gap-5 xl:grid-cols-[1fr_360px]"><Panel title="Integrantes">{people.map(p=><div key={p.id} className="mb-3 flex items-center gap-4 rounded-2xl border p-4"><span className="grid size-10 place-items-center rounded-full bg-[#f8f0dc] font-bold text-[#8a5e08]">{p.full_name.slice(0,2).toUpperCase()}</span><div className="min-w-0 flex-1"><p className="font-bold">{p.full_name}</p><p className="truncate text-sm text-slate-500">{p.email}</p></div><Badge variant="secondary">{p.member_role==="coordinator"?"Coordinador":"Integrante"}</Badge></div>)}</Panel><aside className="rounded-[24px] bg-[#003f32] p-5 text-white"><h2 className="font-bold text-[#f3d277]">Resumen</h2><div className="mt-5 space-y-4"><Dark label="Código" value={preview?"GRP-DEMO":String(group?.data.code||"—")}/><Dark label="Plan" value={preview?"Gold":String(group?.data.plan||"Sin plan")}/><Dark label="Integrantes" value={`${people.length}/3`}/></div></aside></div></div>}
function StudentPlan({profile,group,rows,preview,mutate,upload}:{profile:Profile;group?:Row;rows:Row[];preview:boolean;mutate:Mutate;upload:(f:File,k:string,g?:string)=>Promise<any>}){const[plan,setPlan]=useState("Gold"),[amount,setAmount]=useState(""),[file,setFile]=useState<File|null>(null),[busy,setBusy]=useState(false);const coordinator=preview||profile.member_role==="coordinator";return <div className="space-y-6"><Header eyebrow="Mi plan y pagos" title={`Plan ${preview?"Gold":String(group?.data.plan||"Sin plan")}`} description="La renovación no es automática y se activa después de aprobar el comprobante."/><div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><aside className="rounded-[24px] bg-[#003f32] p-6 text-white"><p className="text-sm font-bold text-[#f3d277]">Vigencia</p><p className="mt-4 text-5xl font-extrabold">{preview?18:remaining(group?.data.endsAt as string)}</p><p className="text-sm text-slate-300">días restantes</p></aside><Panel title="Reportar pago completo">{coordinator?<><div className="grid gap-4 sm:grid-cols-2"><Field label="Plan"><Select value={plan} onValueChange={setPlan}><SelectTrigger className="w-full"><SelectValue/></SelectTrigger><SelectContent><SelectItem value="Bronce">Bronce</SelectItem><SelectItem value="Plata">Plata</SelectItem><SelectItem value="Gold">Gold</SelectItem></SelectContent></Select></Field><Field label="Valor USD"><Input type="number" value={amount} onChange={e=>setAmount(e.target.value)}/></Field></div><FilePicker file={file} setFile={setFile} label="Comprobante"/><Button disabled={busy||preview} className="w-full bg-[#003f32]" onClick={async()=>{if(!file||!amount)return toast.error("Completa el valor y comprobante.");setBusy(true);const stored=await upload(file,"payment");if(stored)await mutate({action:"report_payment",plan,amount:Number(amount),proofKey:stored.key,proofFileName:stored.fileName},"Comprobante enviado.");setBusy(false)}}>{busy?<RefreshCw className="animate-spin"/>:<Send/>} {preview?"Vista previa":"Enviar comprobante"}</Button></>:<p className="rounded-2xl bg-[#fff7e5] p-4 text-sm text-[#76520a]">Solo el coordinador puede reportar el pago completo.</p>}</Panel></div>{rows.map(r=><article key={r.id} className="flex items-center justify-between rounded-2xl border bg-white p-4"><div><p className="font-bold">{r.title}</p><p className="text-sm text-slate-500">${Number(r.data.amount||0).toFixed(2)} · {date(r.created_at)}</p></div><Status status={r.status}/></article>)}</div>}
function NoticeList({rows,profileId,mutate}:{rows:Row[];profileId:string;mutate:Mutate}){return <div className="space-y-6"><Header eyebrow="Notificaciones" title="Avisos importantes" description="Pagos, vencimientos, materiales, plazos y revisiones."/>{rows.length?rows.map(r=>{const read=Array.isArray(r.data.readBy)&&r.data.readBy.includes(profileId);return <button key={r.id} onClick={()=>!read&&mutate({action:"mark_notice",id:r.id})} className={`flex w-full gap-4 rounded-2xl border p-4 text-left ${read?"bg-white":"border-[#d7b966] bg-[#f1faf8]"}`}><span className={`mt-2 size-2 rounded-full ${read?"bg-slate-300":"bg-[#d6a32b]"}`}/><span><strong>{r.title}</strong><small className="mt-1 block text-sm leading-6 text-slate-600">{String(r.data.body||"")}</small></span></button>}):<Empty icon={Bell} title="No tienes avisos" text="Las notificaciones aparecerán aquí."/>}</div>}
function Account({profile}:{profile:Profile}){const statusLabel:Record<string,string>={active:"Activo",invited:"Invitado",suspended:"Suspendido"};return <div className="space-y-6"><Header eyebrow="Mi cuenta" title="Datos de acceso" description="La cédula nunca se utiliza como contraseña ni se muestra completa."/><div className="grid gap-5 xl:grid-cols-[1fr_360px]"><Panel title="Información personal"><div className="grid gap-4 sm:grid-cols-2"><Read label="Nombre" value={profile.full_name}/><Read label="Correo" value={profile.email}/><Read label="Cédula" value={profile.identifier_last4?`••••••${profile.identifier_last4}`:"No registrada"}/><Read label="Estado" value={statusLabel[profile.status]||profile.status}/></div></Panel><aside className="rounded-[24px] bg-[#003f32] p-5 text-white"><ShieldCheck className="size-7 text-[#edc764]"/><h2 className="mt-4 font-bold">Acceso protegido</h2><p className="mt-3 text-sm leading-6 text-slate-300">Tu sesión de ChatGPT identifica la cuenta; TUTOSEBAS controla grupo, plan y permisos.</p><Button asChild className="mt-6 w-full bg-white text-[#003f32]"><a href="/signout-with-chatgpt?return_to=/" target="_top">Cerrar sesión</a></Button></aside></div></div>}

function Apa({plan}:{plan:string}){const[tab,setTab]=useState("guide"),[ref,setRef]=useState(""),[result,setResult]=useState<string[]>([]),[checks,setChecks]=useState<boolean[]>(Array(6).fill(false));const verify=()=>{const found:string[]=[];if(!/(19|20)\d{2}|s\.?\s*f\.?/i.test(ref))found.push("Falta el año o la indicación “s. f.”.");if(!/^.{2,100}\([^)]+\)/.test(ref))found.push("Revisa autor o institución antes de la fecha.");if(!/https?:\/\/|doi\.org/i.test(ref))found.push("Comprueba si la fuente digital necesita URL o DOI.");setResult(found.length?found:["La estructura general parece completa; verifica cursivas y mayúsculas."])};return <div className="space-y-5"><section className="rounded-[26px] bg-[#003f32] p-6 text-white"><Badge className="border-0 bg-[#f4c45b] text-[#4d3700]">APA 7</Badge><h2 className="mt-4 text-2xl font-extrabold">Centro de Normas APA</h2><p className="mt-2 text-sm text-slate-300">Guía, citas, referencias, plantillas, curso y verificador orientativo.</p></section><Tabs value={tab} onValueChange={setTab}><TabsList className="mb-5 h-auto w-full justify-start overflow-x-auto overflow-y-hidden rounded-2xl border bg-white p-1.5 [scrollbar-width:none] [&::-webkit-scrollbar]:hidden"><TabsTrigger className="min-h-10 flex-none px-4 text-sm sm:flex-1" value="guide">Guía rápida</TabsTrigger><TabsTrigger className="min-h-10 flex-none px-4 text-sm sm:flex-1" value="quotes">Citas</TabsTrigger><TabsTrigger className="min-h-10 flex-none px-4 text-sm sm:flex-1" value="refs">Referencias</TabsTrigger><TabsTrigger className="min-h-10 flex-none px-4 text-sm sm:flex-1" value="course">Curso</TabsTrigger><TabsTrigger className="min-h-10 flex-none px-4 text-sm sm:flex-1" value="verify">Verificador</TabsTrigger></TabsList><TabsContent value="guide"><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-4">{["Formato general","Portada y títulos","Tablas y figuras","Revisión final"].map(x=><article key={x} className="rounded-2xl border bg-white p-5"><BookText className="size-5 text-[#8a5e08]"/><h3 className="mt-3 font-bold">{x}</h3><p className="mt-2 text-sm text-slate-600">Explicación clara, ejemplos y comprobación antes de entregar.</p></article>)}</div><Panel title="Lista antes de entregar"><div className="space-y-3">{["Formato general revisado","Todas las citas aparecen en referencias","Todas las referencias fueron citadas","Citas textuales con página","Tablas y figuras identificadas","Enlaces verificados"].map((x,i)=><label key={x} className="flex gap-3 rounded-xl border p-3"><Checkbox checked={checks[i]} onCheckedChange={v=>setChecks(c=>c.map((a,j)=>j===i?Boolean(v):a))}/><span className="text-sm">{x}</span></label>)}</div></Panel></TabsContent><TabsContent value="quotes"><div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">{[["Narrativa","Pérez (2024) sostiene que…"],["Parentética","…en el proceso (Pérez, 2024)."],["Textual corta","“Fragmento” (Pérez, 2024, p. 18)."],["Textual larga","Bloque independiente con sangría."],["Paráfrasis","Idea propia con atribución."],["Institucional","Ministerio de Educación (2024)…"]].map(([a,b])=><article key={a} className="rounded-2xl border bg-white p-5"><h3 className="font-bold">{a}</h3><p className="mt-3 rounded-xl bg-slate-50 p-3 text-sm">{b}</p></article>)}</div></TabsContent><TabsContent value="refs"><Panel title="Modelos por fuente"><div className="grid gap-3 md:grid-cols-2">{["Libro","Artículo científico","Página web","Video de YouTube","Documento institucional","Tesis"].map(x=><div key={x} className="rounded-xl bg-slate-50 p-4"><strong>{x}</strong><p className="mt-2 text-sm text-slate-600">Autor. (Año). Título. Editorial o sitio. URL/DOI</p></div>)}</div></Panel></TabsContent><TabsContent value="course">{plan==="Gold"?<Panel title="Curso APA aplicado"><p className="text-sm text-slate-600">4 lecciones · 68 minutos · videos, ejercicios y progreso.</p></Panel>:<Locked plan="Gold"/>}</TabsContent><TabsContent value="verify">{plan==="Gold"?<div className="grid gap-5 xl:grid-cols-[1fr_380px]"><Panel title="Revisar una referencia"><Textarea value={ref} onChange={e=>setRef(e.target.value)} className="min-h-36" placeholder="Pega la referencia completa"/><Button onClick={verify} className="bg-[#003f32]"><Sparkles/> Revisar estructura</Button></Panel><Panel title="Resultado">{result.length?result.map(x=><p key={x} className="mb-3 rounded-xl bg-slate-50 p-3 text-sm">{x}</p>):<p className="text-sm text-slate-500">El resultado aparecerá aquí.</p>}</Panel></div>:<Locked plan="Gold"/>}</TabsContent></Tabs></div>}

function Header({eyebrow,title,description,action}:{eyebrow:string;title:string;description:string;action?:ReactNode}){return <header className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between"><div><p className="text-sm font-bold text-[#8a5e08]">{eyebrow}</p><h1 className="mt-1 text-2xl font-extrabold tracking-[-.03em] sm:text-3xl">{title}</h1><p className="mt-2 max-w-3xl text-base leading-7 text-slate-600">{description}</p></div>{action}</header>}
function Hero({eyebrow,title,description}:{eyebrow:string;title:string;description:string}){return <section className="rounded-[28px] bg-[#003f32] p-7 text-white"><Badge className="border-0 bg-[#d6a32b] text-[#392600]">{eyebrow}</Badge><h1 className="mt-5 text-3xl font-extrabold tracking-[-.04em] md:text-4xl">{title}</h1><p className="mt-3 max-w-2xl text-slate-300">{description}</p></section>}
function Metric({icon:Icon,label,value,note,tone="teal"}:{icon:ComponentType<{className?:string}>;label:string;value:string|number;note:string;tone?:string}){const color=tone==="gold"?"bg-[#fff4d9] text-[#936000]":tone==="coral"?"bg-[#fff0eb] text-[#a94d35]":tone==="navy"?"bg-[#eaf0f5] text-[#0a4b3e]":"bg-[#fbf1d8] text-[#785208]";return <article className="rounded-[22px] border bg-white p-5 shadow-[0_12px_35px_rgba(16,42,67,.05)]"><div className="flex justify-between"><div><p className="text-sm font-semibold text-slate-500">{label}</p><p className="mt-2 text-3xl font-extrabold">{value}</p></div><span className={`grid size-11 place-items-center rounded-2xl ${color}`}><Icon className="size-5"/></span></div><p className="mt-3 text-sm text-slate-500">{note}</p></article>}
function Panel({title,children}:{title:string;children:ReactNode}){return <section className="space-y-4 rounded-[24px] border bg-white p-5 md:p-6"><h2 className="text-xl font-bold">{title}</h2>{children}</section>}
const humanStatus=(status:string)=>({active:"Activo",approved:"Aprobado",published:"Publicado",finalized:"Finalizado",delivered:"Entregado",pending:"Pendiente",invited:"Invitado",draft:"Borrador",received:"Recibido",deadline_set:"Plazo asignado",in_review:"En revisión",new_version:"Nueva versión",rejected:"Rechazado",suspended:"Suspendido",archived:"Histórico",changes_requested:"Requiere ajustes",read:"Leído"} as Record<string,string>)[status]||status;
function Status({status}:{status:string}){const ok=["active","approved","published","finalized","delivered"].includes(status),warn=["pending","invited","draft","received","deadline_set","in_review","new_version"].includes(status);return <Badge className={`border-0 ${ok?"bg-emerald-100 text-emerald-800":warn?"bg-amber-100 text-amber-800":"bg-slate-100 text-slate-700"}`}>{humanStatus(status)}</Badge>}
function Info({label,value}:{label:string;value:string}){return <div className="mb-3 flex justify-between rounded-xl bg-slate-50 px-4 py-3 text-sm"><span className="text-slate-500">{label}</span><strong>{value}</strong></div>}
function ActionRows({rows}:{rows:Array<[number,string,ComponentType<{className?:string}>]>}){return <div className="grid gap-3 md:grid-cols-2">{rows.map(([n,t,Icon])=><div key={t} className="flex items-center gap-4 rounded-2xl border p-4"><span className="grid size-10 place-items-center rounded-xl bg-[#f8f0dc] text-[#8a5e08]"><Icon className="size-5"/></span><strong>{n} · {t}</strong></div>)}</div>}
function Empty({icon:Icon,title,text}:{icon:ComponentType<{className?:string}>;title:string;text:string}){return <div className="rounded-[22px] border border-dashed bg-white p-10 text-center"><Icon className="mx-auto size-8 text-slate-400"/><h3 className="mt-4 font-bold">{title}</h3><p className="mt-2 text-sm text-slate-500">{text}</p></div>}
function Field({label,children}:{label:string;children:ReactNode}){return <label className="block"><span className="mb-2 block text-sm font-bold text-[#0b5143]">{label}</span>{children}</label>}
function FilePicker({file,setFile,label,accept=".pdf,.docx,.pptx,.png,.jpg,.jpeg"}:{file:File|null;setFile:(f:File|null)=>void;label:string;accept?:string}){const effectiveAccept=label==="Comprobante"?".pdf,.png,.jpg,.jpeg":accept.split(",").filter(value=>![".doc",".ppt"].includes(value.trim().toLowerCase())).join(",");return <label className="flex cursor-pointer items-center gap-3 rounded-2xl border-2 border-dashed border-[#d8bd78] bg-[#fffaf1] p-4"><UploadCloud className="size-5 text-[#8a5e08]"/><span className="min-w-0 flex-1 truncate text-sm font-semibold">{file?.name||label}</span><input type="file" className="hidden" accept={effectiveAccept} onChange={e=>{const selected=e.target.files?.[0]||null;if(selected&&selected.size>25*1024*1024){toast.error("El archivo supera 25 MB.");e.currentTarget.value="";setFile(null);return;}setFile(selected)}}/></label>}
function Locked({plan}:{plan:string}){return <div className="rounded-[22px] border bg-white p-10 text-center"><LockKeyhole className="mx-auto size-8 text-[#8a5e08]"/><h3 className="mt-4 font-bold">Disponible con el plan {plan}</h3><p className="mt-2 text-sm text-slate-500">El profesor también puede habilitarlo manualmente.</p></div>}
function Read({label,value}:{label:string;value:string}){return <div className="rounded-2xl bg-slate-50 p-4"><p className="text-xs font-bold uppercase text-slate-400">{label}</p><p className="mt-2 break-words font-semibold">{value}</p></div>}
function ReportValue({label,value}:{label:string;value:string}){return <div className="rounded-xl bg-slate-50 p-3"><p className="text-xs font-semibold text-slate-500">{label}</p><p className="mt-1 font-extrabold text-[#15352d]">{value}</p></div>}
function Dark({label,value}:{label:string;value:string}){return <div className="flex justify-between gap-4 text-sm"><span className="text-slate-400">{label}</span><strong className="text-right">{value}</strong></div>}
function Brand(){return <div className="flex items-center gap-3 px-5 py-6"><span className="grid size-11 place-items-center rounded-2xl bg-[#d6a32b] text-[#392600]"><BookOpenCheck className="size-5"/></span><span><strong className="block text-lg">TUTOSEBAS</strong><small className="text-slate-300">Acompañamiento UIC</small></span></div>}
function ModeSwitch({mode,change}:{mode:string;change:(m:"admin"|"student")=>void}){return <div className="mx-4 mb-4 grid grid-cols-2 rounded-xl bg-white/8 p-1"><button onClick={()=>change("admin")} className={`rounded-lg px-3 py-2 text-xs font-bold ${mode==="admin"?"bg-white text-[#003f32]":"text-slate-300"}`}>Profesor</button><button onClick={()=>change("student")} className={`rounded-lg px-3 py-2 text-xs font-bold ${mode==="student"?"bg-white text-[#003f32]":"text-slate-300"}`}>Estudiante</button></div>}
function Nav({items,active,go,unread=0}:{items:readonly NavItem[];active:string;go:(id:string)=>void;unread?:number}){return <nav className="scrollbar-thin flex-1 overflow-y-auto px-3 pb-5">{items.map(([id,label,Icon])=><button key={id} onClick={()=>go(id)} className={`mb-1 flex w-full items-center gap-3 rounded-xl px-3.5 py-3 text-left text-sm font-semibold ${active===id?"bg-white text-[#003f32]":"text-slate-300 hover:bg-white/8 hover:text-white"}`}><Icon className="size-[18px]"/><span className="flex-1">{label}</span>{id==="notices"&&unread>0&&<span aria-label={`${unread} aviso${unread===1?"":"s"} sin leer`} className="grid min-h-5 min-w-5 place-items-center rounded-full bg-red-600 px-1.5 text-[10px] font-extrabold leading-none text-white">{unread>99?"99+":unread}</span>}</button>)}</nav>}
function Security(){return <div className="mt-auto p-4"><div className="rounded-2xl border border-white/10 bg-white/6 p-4"><p className="flex items-center gap-2 text-xs font-bold text-[#f3d277]"><ShieldCheck className="size-4"/> Acceso protegido</p><p className="mt-2 text-xs leading-5 text-slate-400">Cuenta, grupo, plan y archivos se validan en cada solicitud.</p></div></div>}
function Loading(){return <div className="grid min-h-screen place-items-center bg-[#f7f5f0]"><RefreshCw className="size-8 animate-spin text-[#8a5e08]"/></div>}
function ErrorView({message,retry}:{message:string;retry:()=>void}){return <main className="grid min-h-screen place-items-center bg-[#f7f5f0] p-5"><div className="max-w-lg rounded-[26px] border bg-white p-8 text-center"><FolderCog className="mx-auto size-9 text-[#8a5e08]"/><h1 className="mt-4 text-2xl font-extrabold">No pudimos abrir la plataforma</h1><p className="mt-3 text-sm text-slate-600">{message}</p><Button onClick={retry} className="mt-6 bg-[#003f32]">Reintentar</Button></div></main>}
function Pending({data}:{data:Workspace}){return <main className="grid min-h-screen place-items-center bg-[#f7f5f0] p-5"><div className="max-w-xl rounded-[28px] border bg-white p-8 text-center"><ShieldCheck className="mx-auto size-10 text-[#8a5e08]"/><h1 className="mt-5 text-2xl font-extrabold">Acceso pendiente</h1><p className="mt-3 text-slate-600">El correo <strong>{data.identity.email}</strong> todavía no está activo. Pide al profesor que lo registre o habilite.</p><Button asChild variant="outline" className="mt-6"><a href="/signout-with-chatgpt?return_to=/" target="_top">Usar otra cuenta</a></Button></div></main>}
function date(value?:string){if(!value)return "Sin fecha";const d=new Date(value);return Number.isNaN(d.getTime())?value:new Intl.DateTimeFormat("es-EC",{day:"2-digit",month:"short",year:"numeric"}).format(d)}
function dateOnly(value:unknown){const raw=String(value||"").slice(0,10);return /^\d{4}-\d{2}-\d{2}$/.test(raw)?new Intl.DateTimeFormat("es-EC",{day:"2-digit",month:"short",year:"numeric",timeZone:"UTC"}).format(new Date(`${raw}T00:00:00Z`)):date(raw)}
function workTypeLabel(value:unknown){return value==="planning"?"Planificación curricular":value==="case-study"?"Estudio de caso":String(value||"Trabajo UIC")}
function dateTime(value?:string){if(!value)return "Sin fecha";const d=new Date(value);return Number.isNaN(d.getTime())?value:new Intl.DateTimeFormat("es-EC",{day:"2-digit",month:"short",year:"numeric",hour:"2-digit",minute:"2-digit"}).format(d)}
function duration(seconds:number){if(!Number.isFinite(seconds)||seconds<=0)return "Duración no registrada";const minutes=Math.floor(seconds/60),rest=Math.round(seconds%60);return minutes?`${minutes} min ${rest} s`:`${rest} s`}
function attemptTime(attempt:Row){const value=String(attempt.data.completedAt||attempt.created_at);const time=new Date(value).getTime();return Number.isNaN(time)?0:time}
function remaining(value?:string){if(!value)return 0;return Math.max(0,Math.ceil((new Date(value).getTime()-Date.now())/86400000))}
